Translate("esES", "genn-greymane", {
	title = "Genn Greymane",
	subtitle = "Rey de Gilneas",
	found = "Tras la Muralla de Cringrís, en Gilneas",
	hint = "Conozca al rey cuya muralla sella el sur de Argénteos.",
	allegiance = "Reino de Gilneas",
	aliases = { "Greymane", "rey Greymane", "rey Genn Greymane" },
	sections = {
		{
			title = "Resumen",
			text = [=[Genn Greymane es el rey de {link:gilneas}Gilneas{/link}. Es un gobernante orgulloso y obstinado, un guerrero que confía en su propio pueblo y en pocos más. Fue él quien retiró a Gilneas de la {link:alliance}Alianza{/link} tras la {link:second-war}Segunda Guerra{/link}, y quien levantó la gran muralla a lo largo del sur de {link:silverpine-forest}Argénteos{/link}. Tras esa muralla, su reino se ha guardado sus propios consejos durante toda la ruina del norte.]=],
		},
		{
			title = "Importancia",
			text = [=[Greymane es el señor que eligió estar solo. Su muralla ahorró a {link:gilneas}Gilneas{/link} el coste de las guerras de otras naciones. También dejó al norte frente a la {link:scourge}Plaga{/link} sin el ejército gilneano. Si la muralla salvó su reino o solo lo ocultó, nadie desde fuera puede saberlo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Cuando cayó {link:stormwind-city}Ventormenta{/link}, acudió con los demás gobernantes humanos al consejo en {link:lordaeron}Lordaeron{/link} convocado por el rey {link:terenas-menethil}Terenas{/link}. Dudó del peligro, y se jactó de que el ejército de {link:gilneas}Gilneas{/link} podía hacer frente a cualquier amenaza.
• Se unió a regañadientes a la {link:alliance}Alianza de Lordaeron{/link}, y le dio mucho menos de lo que su reino podría haber dado.
• Tras la guerra discutió con los demás reyes por el coste de los campos de internamiento de orcos y del {link:nethergarde-keep}Castillo de Nethergarde{/link}. Cuando se quejó del gasto de la fortaleza, el joven rey {link:varian-wrynn}Varian Wrynn{/link} respondió que no se podía poner precio a su seguridad.
• Buscó influir en el destino de {link:alterac-mountains}Alterac{/link}, sin señor, y apoyó a un pretendiente a su trono.
• Retiró a Gilneas de la Alianza, construyó la {link:the-greymane-wall}Muralla de Cringrís{/link} y cerró sus puertas.]=],
		},
		{
			title = "Sin registro",
			text = [=[No ha salido ninguna noticia de {link:gilneas}Gilneas{/link} desde que se cerraron sus puertas. Lo que el rey Greymane sabe de los ferocanis a su puerta, y lo que ocurre en su reino, ninguna crónica de estos días puede decirlo.]=],
		},
	},
	chapters = {
		{
			title = "La muralla de su nombre",
			hint = "Deténgase ante la muralla que lleva el nombre del rey.",
			text = [=[Greymane creía que {link:gilneas}Gilneas{/link} no debía nada a las guerras de otros reinos. Cuando la {link:alliance}Alianza{/link} pidió a su pueblo que pagara los campos de prisioneros de los orcos, se negó, y sacó a su reino de la Alianza por completo. Después lo amuralló. {link:the-greymane-wall}La Muralla de Cringrís{/link} se alzó a lo largo de la frontera norte de Gilneas. Cuando la peste llegó a {link:lordaeron}Lordaeron{/link}, sus puertas siguieron cerradas. Ningún ejército gilneano marchó al norte para ayudar al reino moribundo.]=],
		},
		{
			title = "Las puertas cerradas",
			hint = [=[Ayude a los Renegados a impedir que la maldición se extienda entre los refugiados de la muralla.]=],
			text = [=[Ahora los refugiados del norte se apiñan al pie de la muralla, enfermos y hambrientos. Esperaban encontrar refugio en {link:gilneas}Gilneas{/link}. Los gilneanos han dejado claro que no dejarán pasar a nadie. A los {link:forsaken}Renegados{/link}, que temen la maldición de los ferocanis, eso los tranquiliza. Dicen que al menos la maldición no puede cruzar las puertas.]=],
		},
	},
	mentions = {
		{ text = "Detener la propagación" },
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "convocó el consejo al que se unió" },
		{ id = "the-greymane-wall", name = "La Muralla de Cringrís", note = "su obra" },
	},
})
